using Microsoft.ML;
using TicketClassifier.Models;

namespace TicketClassifier.Services;

public class TicketClassifierService
{
    private readonly MLContext _mlContext;
    private readonly ITransformer _model;
    private readonly PredictionEngine<TicketData, TicketPrediction> _predictionEngine;
    private readonly IReadOnlyList<string> _categoryLabels;
    private readonly EvaluationResponse _metrics;

    public TicketClassifierService(string dataPath)
    {
        _mlContext = new MLContext(seed: 42);

        var dataView = _mlContext.Data.LoadFromTextFile<TicketData>(
            dataPath, hasHeader: true, separatorChar: ',', allowQuoting: true);

        var pipeline = _mlContext.Transforms.Conversion.MapValueToKey("Label", nameof(TicketData.Category))
            .Append(_mlContext.Transforms.Text.FeaturizeText("SubjectFeaturized", nameof(TicketData.Subject)))
            .Append(_mlContext.Transforms.Text.FeaturizeText("DescriptionFeaturized", nameof(TicketData.Description)))
            .Append(_mlContext.Transforms.Concatenate("Features", "SubjectFeaturized", "DescriptionFeaturized", nameof(TicketData.Priority)))
            .Append(_mlContext.Transforms.NormalizeMinMax("Features"))
            .Append(_mlContext.MulticlassClassification.Trainers.SdcaMaximumEntropy("Label", "Features"))
            .Append(_mlContext.Transforms.Conversion.MapKeyToValue("PredictedLabel"));

        _model = pipeline.Fit(dataView);
        _predictionEngine = _mlContext.Model.CreatePredictionEngine<TicketData, TicketPrediction>(_model);

        // Extract ordered label names from the key-value mapping
        var labelColumn = dataView.Schema["Category"];
        var keyColumn = _model.GetOutputSchema(dataView.Schema)["Label"];
        VBuffer<ReadOnlyMemory<char>> keys = default;
        keyColumn.GetKeyValues(ref keys);
        _categoryLabels = keys.DenseValues().Select(v => v.ToString()).ToList();

        // Evaluate with cross-validation on the small dataset
        var cvResults = _mlContext.MulticlassClassification.CrossValidate(dataView, pipeline, numberOfFolds: 3, labelColumnName: "Label");
        var best = cvResults.OrderByDescending(r => r.Metrics.MacroAccuracy).First();
        var metrics = best.Metrics;

        // Per-category metrics from the confusion matrix
        var perCategory = new List<CategoryMetric>();
        var cm = metrics.ConfusionMatrix;
        for (int i = 0; i < cm.PerClassPrecision.Count; i++)
        {
            perCategory.Add(new CategoryMetric
            {
                Category = i < _categoryLabels.Count ? _categoryLabels[i] : $"Class {i}",
                Precision = cm.PerClassPrecision[i],
                Recall = cm.PerClassRecall[i],
                F1Score = cm.PerClassPrecision[i] + cm.PerClassRecall[i] > 0
                    ? 2 * cm.PerClassPrecision[i] * cm.PerClassRecall[i] / (cm.PerClassPrecision[i] + cm.PerClassRecall[i])
                    : 0
            });
        }

        _metrics = new EvaluationResponse
        {
            MicroAccuracy = (float)metrics.MicroAccuracy,
            MacroAccuracy = (float)metrics.MacroAccuracy,
            LogLoss = (float)metrics.LogLoss,
            LogLossReduction = (float)metrics.LogLossReduction,
            PerCategory = perCategory
        };
    }

    public TicketPredictionResponse Predict(TicketRequest request)
    {
        var prediction = _predictionEngine.Predict(new TicketData
        {
            Subject = request.Subject,
            Description = request.Description,
            Priority = request.Priority
        });

        var confidence = new Dictionary<string, float>();
        for (int i = 0; i < prediction.Score.Length && i < _categoryLabels.Count; i++)
        {
            confidence[_categoryLabels[i]] = prediction.Score[i];
        }

        return new TicketPredictionResponse
        {
            PredictedCategory = prediction.Category,
            Confidence = confidence
        };
    }

    public EvaluationResponse GetMetrics() => _metrics;
}

